def check_solution(M, x):
    # Condition (1): x0 = 1
    if x[0] != 1:
        return False
    # Condition (2): x_{i+1} >= 1 + (x_i^3 - x_i^2) / x_{i-1}
    for i in range(1, M):
        lower_bound = 1 + (x[i]**3 - x[i]**2) / x[i-1]
        if x[i+1] < lower_bound:
            return False
    # Condition (3): sum(x_{i-1} / x_i) = 0.9375
    total_sum = sum(x[i-1] / x[i] for i in range(1, M + 1))
    return abs(total_sum - 0.9375) < 1e-9

sol = (4, [1, 2, 5, 134, 718240])
