print(f"Result: {check_solution(M, x)}")

def check_recurrence(x):
    for i in range(1, len(x) - 1):
        expected = 1 + (x[i]**3 - x[i]**2) / x[i-1]
        if x[i+1] != expected:
            return False
    return True

